def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits.

    x is an integer in 0..255. k is an integer in 0..7.
    Bits shifted out of the high end wrap around to the low end.
    The result is an integer in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0, 0) == 0
    assert rotl8(1, 0) == 1
    assert rotl8(0xA5, 0) == 0xA5
    assert rotl8(255, 0) == 255


def test_rotl8_zero_stays_zero() -> None:
    for k in range(8):
        assert rotl8(0, k) == 0


def test_rotl8_single_bit_moves_left() -> None:
    assert rotl8(1, 1) == 2
    assert rotl8(1, 7) == 128
    assert rotl8(0b0100_0000, 1) == 0b1000_0000


def test_rotl8_high_bit_wraps_to_low() -> None:
    assert rotl8(0b1000_0000, 1) == 0b0000_0001
    assert rotl8(0b1000_0001, 1) == 0b0000_0011
    assert rotl8(0b1000_0000, 7) == 0b0100_0000


def test_rotl8_nibble_swap() -> None:
    assert rotl8(0x12, 4) == 0x21
    assert rotl8(0xAB, 4) == 0xBA


def test_rotl8_all_ones_is_fixed() -> None:
    for k in range(8):
        assert rotl8(255, k) == 255


def test_rotl8_full_cycle_returns_original() -> None:
    for x in (0x00, 0x01, 0x5A, 0x81, 0xFF):
        assert rotl8(x, 8 - 8) == x
        assert rotl8(rotl8(x, 3), 5) == x


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255
